import { useCallback } from 'react';
import { useSelector } from 'react-redux';
import { LanguageType } from '@Store/slice/language';
const isLocalized = (value) => typeof value === 'object' && value !== null && 'ko' in value && 'en' in value;
/**
 * 현재 언어로 값을 고릅니다.
 * 이미 번역이 필요 없는 원시값(기술명 등)이 들어와도 그대로 통과시킵니다.
 */
export const localize = (value, language) => isLocalized(value) ? value[language] : value;
/**
 * 현재 언어와 번역 헬퍼를 함께 돌려줍니다.
 *
 *   const {t, language} = useLocale();
 *   <h2>{t(project.title)}</h2>
 */
export const useLocale = () => {
    const language = useSelector((state) => state.language.value);
    const t = useCallback((value) => localize(value, language), [language]);
    return { language, t, isKorean: language === LanguageType.KO };
};
export default useLocale;
